import{_ as s,o as a,c as i,ag as t}from"./chunks/framework.CZxGLIO_.js";const k=JSON.parse('{"title":"Installation and first start","description":"Choose a GooseForum release, build from source, and verify your first installation.","frontmatter":{"title":"Installation and first start","description":"Choose a GooseForum release, build from source, and verify your first installation."},"headers":[],"relativePath":"en/docs/gooseforum/installation/index.md","filePath":"en/docs/gooseforum/installation/index.md"}'),n={name:"en/docs/gooseforum/installation/index.md"};function o(r,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="installation-and-first-start" tabindex="-1">Installation and first start <a class="header-anchor" href="#installation-and-first-start" aria-label="Permalink to &quot;Installation and first start&quot;">​</a></h1><p>For a first deployment, use a release archive: the server does not need Go, Node.js or pnpm. These instructions were checked against <strong>v0.2.122</strong>. Source requirements depend on the selected version&#39;s <code>go.mod</code> and frontend dependencies.</p><h2 id="choose-an-archive" tabindex="-1">Choose an archive <a class="header-anchor" href="#choose-an-archive" aria-label="Permalink to &quot;Choose an archive&quot;">​</a></h2><p>Select a version in <a href="https://github.com/leancodebox/GooseForum/releases" target="_blank" rel="noreferrer">Releases</a>, then match your OS and CPU:</p><table tabindex="0"><thead><tr><th>OS</th><th>Intel / AMD 64-bit</th><th>ARM 64-bit</th></tr></thead><tbody><tr><td>Linux</td><td><code>GooseForum_Linux_x86_64.tar.gz</code></td><td><code>GooseForum_Linux_arm64.tar.gz</code></td></tr><tr><td>macOS</td><td><code>GooseForum_Darwin_x86_64.tar.gz</code></td><td><code>GooseForum_Darwin_arm64.tar.gz</code></td></tr><tr><td>Windows</td><td><code>GooseForum_Windows_x86_64.zip</code></td><td><code>GooseForum_Windows_arm64.zip</code></td></tr></tbody></table><p>On Linux or macOS, use <code>uname -m</code>: <code>x86_64</code> means Intel / AMD; <code>arm64</code> or <code>aarch64</code> means ARM. Download the checksums file from the same release and verify the archive&#39;s SHA-256. Do not use a checksum from another release.</p><h2 id="start-the-forum" tabindex="-1">Start the forum <a class="header-anchor" href="#start-the-forum" aria-label="Permalink to &quot;Start the forum&quot;">​</a></h2><p>Linux x86_64 example, using a directory where the forum&#39;s data will remain:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/GooseForum_Linux_x86_64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GooseForum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Replace <code>/path/to/</code> with your download directory. On macOS use the matching Darwin archive. On Windows extract the ZIP, enter the directory in PowerShell, and run <code>./GooseForum.exe serve</code>.</p><p>First startup creates <code>config.toml</code> in the working directory. The generated defaults use SQLite and port <code>5234</code>. Open <code>http://localhost:5234</code>, checking the startup log for the actual port. Always start from the same working directory; a different directory may load a different configuration or create a new database.</p><ol><li>Confirm the home page loads and register your administrator account.</li><li>User ID <code>1</code> in a new database becomes administrator. Redeploying an existing database does not select a new administrator.</li><li>Open the admin area, set site information and create a category.</li><li>Publish a test topic and verify replies, image uploads and signing in again.</li><li>Complete <a href="./../administration/">initial administration</a> and <a href="./../deployment/">production deployment</a> before opening registration publicly.</li></ol><h2 id="build-from-source" tabindex="-1">Build from source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from source&quot;">​</a></h2><p>The checked source requires <strong>Go 1.27+</strong>. This guide recommends <strong>Node.js 24 LTS</strong> and pnpm for frontend builds; the Node.js 18 minimum in the upstream README does not describe every current dependency&#39;s requirements.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/leancodebox/GooseForum.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GooseForum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.122</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resource</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ldflags=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-w -s&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Frontend assets are embedded in the Go binary. Build the frontend first, then the backend. Replacing source files or frontend files alone does not update an existing executable. When tracking <code>main</code>, record the commit SHA for reproducible builds and rollback.</p><h2 id="first-checks-when-startup-fails" tabindex="-1">First checks when startup fails <a class="header-anchor" href="#first-checks-when-startup-fails" aria-label="Permalink to &quot;First checks when startup fails&quot;">​</a></h2><ul><li>Port occupied: change <code>port</code> in the existing <code>[server]</code> section and restart.</li><li>An unexpectedly empty forum: check the working directory, configuration and database path before initializing anything.</li><li>A newer Go toolchain is required: check the selected version&#39;s <code>go.mod</code>, or use a release archive.</li><li>Database migration fails: preserve the error and backup; see <a href="./../troubleshooting/">troubleshooting</a>.</li></ul><hr><p>Sources checked on 2026-11-15：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/.goreleaser.yaml" target="_blank" rel="noreferrer">Release build configuration</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/README_ZH.md" target="_blank" rel="noreferrer">README</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/go.mod" target="_blank" rel="noreferrer">Go version</a>。</p>`,20)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
